from aerelith.core.result import Result, E_EMPTY, E_RANGE

def top_by_weight(rows: List[Dict[str, int]], k: int) -> Result:
    if not rows:
        return Result(ok=False, value=None, err=E_EMPTY)
    if k < 1 or k > len(rows):
        return Result(ok=False, value=None, err=E_RANGE)
    sorted_rows = sorted(rows, key=lambda r: r['weight'], reverse=True)
    return Result(ok=True, value=sorted_rows[:k], err=None)
