def top_by_weight(rows: List[Dict[str, object]], k: int) -> Result:
    if not rows:
        return Result(ok=False, value=None, err="E_EMPTY")
    if not (1 <= k <= len(rows)):
        return Result(ok=False, value=None, err="E_RANGE")

    # Sort descending by weight
    sorted_rows = sorted(rows, key=lambda r: r["weight"], reverse=True)

